-- =====================================================================
-- 0. SEQUENCES (remplacent les colonnes IDENTITY de 12c)
-- =====================================================================
CREATE SEQUENCE seq_departement          START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_poste                START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_candidat             START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_employeEntreprise    START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_demandeRecru         START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_validation           START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_historiquePrixPostes START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_offreEmploi          START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_candidature          START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_entretien            START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_evaluationCandidat   START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_propositionEmbauche  START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_contrat              START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_posteEmploye         START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_documentCandidat     START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE seq_notification         START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;

-- =====================================================================
-- 1. departement
-- =====================================================================
CREATE TABLE departement (
    id   NUMBER PRIMARY KEY,
    nom  VARCHAR2(150) NOT NULL
);

-- =====================================================================
-- 2. poste  (un POSTE existe indépendamment de l'EMPLOYÉ)
-- =====================================================================
CREATE TABLE poste (
    id             NUMBER PRIMARY KEY,
    id_dept        NUMBER NOT NULL,
    nom            VARCHAR2(150) NOT NULL,
    description    VARCHAR2(4000),
    statut         VARCHAR2(20) DEFAULT 'ACTIF' NOT NULL,
    date_creation  DATE DEFAULT SYSDATE,
    CONSTRAINT fk_poste_dept   FOREIGN KEY (id_dept) REFERENCES departement(id),
    CONSTRAINT ck_poste_statut CHECK (statut IN ('ACTIF', 'ARCHIVE'))
);

-- =====================================================================
-- 3. candidat  (inscription en ligne sur la page publique)
--    CANDIDAT != EMPLOYÉ : tables distinctes
-- =====================================================================
CREATE TABLE candidat (
    id                NUMBER PRIMARY KEY,
    nom               VARCHAR2(100) NOT NULL,
    prenom            VARCHAR2(100),
    email             VARCHAR2(150) NOT NULL,
    mot_de_passe      VARCHAR2(255),            -- stocker un HASH (bcrypt), jamais en clair
    telephone         VARCHAR2(30),
    dateNaissance     DATE,
    adresse           VARCHAR2(255),
    Diplome           VARCHAR2(150),
    experience        VARCHAR2(4000),
    competence        VARCHAR2(4000),
    cv_url            VARCHAR2(500),
    date_inscription  DATE DEFAULT SYSDATE,
    statut_compte     VARCHAR2(20) DEFAULT 'ACTIF' NOT NULL,
    CONSTRAINT uq_candidat_email  UNIQUE (email),
    CONSTRAINT ck_candidat_statut CHECK (statut_compte IN ('ACTIF', 'DESACTIVE'))
);

-- =====================================================================
-- 4. employeEntreprise  (lié au candidat d'origine s'il a été recruté)
-- =====================================================================
CREATE TABLE employeEntreprise (
    id             NUMBER PRIMARY KEY,
    matricule      VARCHAR2(20),
    id_candidat    NUMBER,
    nom            VARCHAR2(100) NOT NULL,
    prenom         VARCHAR2(100),
    email          VARCHAR2(150),
    telephone      VARCHAR2(30),
    dateNaissance  DATE,
    adresse        VARCHAR2(255),
    Diplome        VARCHAR2(150),
    experience     VARCHAR2(4000),
    competence     VARCHAR2(4000),
    date_embauche  DATE,
    statut         VARCHAR2(20) DEFAULT 'ACTIF' NOT NULL,
    role_app       VARCHAR2(20) DEFAULT 'EMPLOYE' NOT NULL,
    CONSTRAINT uq_employe_matricule UNIQUE (matricule),
    CONSTRAINT fk_employe_candidat  FOREIGN KEY (id_candidat) REFERENCES candidat(id),
    CONSTRAINT ck_employe_statut    CHECK (statut IN ('ACTIF', 'INACTIF', 'SORTI')),
    CONSTRAINT ck_employe_role      CHECK (role_app IN ('EMPLOYE', 'MANAGER', 'RH', 'DIRECTION'))
);

-- =====================================================================
-- 5. demandeRecru  (Bloc 1 : besoin exprimé par un manager)
-- =====================================================================
CREATE TABLE demandeRecru (
    id              NUMBER PRIMARY KEY,
    id_poste        NUMBER NOT NULL,
    id_demandeur    NUMBER,
    description     VARCHAR2(4000),
    effectif        NUMBER(3) DEFAULT 1 NOT NULL,
    motif           VARCHAR2(20) DEFAULT 'CREATION' NOT NULL,
    budget          NUMBER(15, 2),
    date_demande    DATE DEFAULT SYSDATE,
    date_souhaitee  DATE,
    statut          VARCHAR2(20) DEFAULT 'EN_ATTENTE' NOT NULL,
    CONSTRAINT fk_demande_poste     FOREIGN KEY (id_poste)     REFERENCES poste(id),
    CONSTRAINT fk_demande_demandeur FOREIGN KEY (id_demandeur) REFERENCES employeEntreprise(id),
    CONSTRAINT ck_demande_effectif  CHECK (effectif > 0),
    CONSTRAINT ck_demande_motif     CHECK (motif IN ('CREATION', 'REMPLACEMENT')),
    CONSTRAINT ck_demande_statut    CHECK (statut IN ('EN_ATTENTE', 'VALIDEE', 'REFUSEE', 'ANNULEE'))
);

-- =====================================================================
-- 6. validation  (workflow Manager -> RH -> Direction)
-- =====================================================================
CREATE TABLE validation (
    id               NUMBER PRIMARY KEY,
    id_demande       NUMBER NOT NULL,
    id_valideur      NUMBER,
    role_valideur    VARCHAR2(20),
    ordre            NUMBER(2),
    etat             VARCHAR2(50) DEFAULT 'EN_ATTENTE',
    commentaire      VARCHAR2(4000),
    date_validation  DATE,
    CONSTRAINT fk_validation_demande  FOREIGN KEY (id_demande)  REFERENCES demandeRecru(id),
    CONSTRAINT fk_validation_valideur FOREIGN KEY (id_valideur) REFERENCES employeEntreprise(id),
    CONSTRAINT ck_validation_role     CHECK (role_valideur IN ('MANAGER', 'RH', 'DIRECTION')),
    CONSTRAINT ck_validation_etat     CHECK (etat IN ('EN_ATTENTE', 'APPROUVEE', 'REFUSEE'))
);

-- =====================================================================
-- 7. historiquePrixPostes
-- =====================================================================
CREATE TABLE historiquePrixPostes (
    id                 NUMBER PRIMARY KEY,
    id_poste           NUMBER NOT NULL,
    prix               NUMBER(15, 2),
    date_modification  DATE DEFAULT SYSDATE,
    CONSTRAINT fk_hist_prix_poste FOREIGN KEY (id_poste) REFERENCES poste(id)
);

-- =====================================================================
-- 8. offreEmploi  (Bloc 2 : publication à partir d'une demande validée)
-- =====================================================================
CREATE TABLE offreEmploi (
    id                 NUMBER PRIMARY KEY,
    id_demande         NUMBER NOT NULL,
    id_publie_par      NUMBER,
    titre              VARCHAR2(200) NOT NULL,
    description_offre  VARCHAR2(4000),
    profil_recherche   VARCHAR2(4000),
    type_contrat       VARCHAR2(20) DEFAULT 'CDI' NOT NULL,
    lieu               VARCHAR2(200),
    nb_postes          NUMBER(3) DEFAULT 1 NOT NULL,
    date_publication   DATE,
    date_cloture       DATE,
    statut             VARCHAR2(20) DEFAULT 'BROUILLON' NOT NULL,
    CONSTRAINT fk_offre_demande  FOREIGN KEY (id_demande)    REFERENCES demandeRecru(id),
    CONSTRAINT fk_offre_publieur FOREIGN KEY (id_publie_par) REFERENCES employeEntreprise(id),
    CONSTRAINT ck_offre_type     CHECK (type_contrat IN ('CDI', 'CDD', 'STAGE', 'FREELANCE')),
    CONSTRAINT ck_offre_statut   CHECK (statut IN ('BROUILLON', 'PUBLIEE', 'CLOTUREE', 'ANNULEE')),
    CONSTRAINT ck_offre_dates    CHECK (date_cloture IS NULL OR date_cloture >= date_publication)
);

-- =====================================================================
-- 9. candidature  (un candidat peut avoir plusieurs candidatures)
-- =====================================================================
CREATE TABLE candidature (
    id                 NUMBER PRIMARY KEY,
    id_candidat        NUMBER NOT NULL,
    id_offre           NUMBER NOT NULL,
    etat               VARCHAR2(50) DEFAULT 'RECUE',
    date_candidature   DATE DEFAULT SYSDATE,
    dateReponse        DATE,
    dateUpdateEtat     DATE,
    lettre_motivation  VARCHAR2(4000),
    cv_url             VARCHAR2(500),
    CONSTRAINT fk_cand_candidat FOREIGN KEY (id_candidat) REFERENCES candidat(id),
    CONSTRAINT fk_cand_offre    FOREIGN KEY (id_offre)    REFERENCES offreEmploi(id),
    CONSTRAINT uq_cand_candidat_offre UNIQUE (id_candidat, id_offre),
    CONSTRAINT ck_cand_etat CHECK (etat IN ('RECUE', 'PRESELECTIONNEE', 'ENTRETIEN', 'RETENUE', 'REFUSEE', 'RETIREE'))
);

-- =====================================================================
-- 10. entretien  (id_employe = recruteur qui mène l'entretien)
-- =====================================================================
CREATE TABLE entretien (
    id              NUMBER PRIMARY KEY,
    id_candidature  NUMBER NOT NULL,
    id_employe      NUMBER NOT NULL,
    date_entretien  DATE,
    type_entretien  VARCHAR2(20) DEFAULT 'RH' NOT NULL,
    mode_entretien  VARCHAR2(20) DEFAULT 'PRESENTIEL' NOT NULL,
    lieu            VARCHAR2(200),
    lien_visio      VARCHAR2(500),
    duree_minutes   NUMBER(4) DEFAULT 45,
    etat            VARCHAR2(50) DEFAULT 'PLANIFIE',
    commentaire     VARCHAR2(4000),
    CONSTRAINT fk_entretien_candidature FOREIGN KEY (id_candidature) REFERENCES candidature(id),
    CONSTRAINT fk_entretien_employe     FOREIGN KEY (id_employe)     REFERENCES employeEntreprise(id),
    CONSTRAINT ck_entretien_type CHECK (type_entretien IN ('RH', 'TECHNIQUE', 'TEST', 'DIRECTION')),
    CONSTRAINT ck_entretien_mode CHECK (mode_entretien IN ('PRESENTIEL', 'VISIO', 'TELEPHONE')),
    CONSTRAINT ck_entretien_etat CHECK (etat IN ('PLANIFIE', 'REALISE', 'ANNULE', 'REPORTE'))
);

-- =====================================================================
-- 11. evaluationCandidat
-- =====================================================================
CREATE TABLE evaluationCandidat (
    id                 NUMBER PRIMARY KEY,
    id_entretien       NUMBER NOT NULL,
    id_evaluateur      NUMBER NOT NULL,
    note_technique     NUMBER(4, 2),
    note_comportement  NUMBER(4, 2),
    note_globale       NUMBER(4, 2),
    appreciation       VARCHAR2(4000),
    decision           VARCHAR2(20),
    date_evaluation    DATE DEFAULT SYSDATE,
    CONSTRAINT fk_eval_entretien  FOREIGN KEY (id_entretien)  REFERENCES entretien(id),
    CONSTRAINT fk_eval_evaluateur FOREIGN KEY (id_evaluateur) REFERENCES employeEntreprise(id),
    CONSTRAINT ck_eval_notes CHECK (
        (note_technique    IS NULL OR note_technique    BETWEEN 0 AND 20) AND
        (note_comportement IS NULL OR note_comportement BETWEEN 0 AND 20) AND
        (note_globale      IS NULL OR note_globale      BETWEEN 0 AND 20)),
    CONSTRAINT ck_eval_decision CHECK (decision IN ('FAVORABLE', 'DEFAVORABLE', 'A_REVOIR'))
);

-- =====================================================================
-- 12. propositionEmbauche  (Bloc 3)
-- =====================================================================
CREATE TABLE propositionEmbauche (
    id                   NUMBER PRIMARY KEY,
    id_candidature       NUMBER NOT NULL,
    salaire_propose      NUMBER(15, 2),
    date_proposition     DATE DEFAULT SYSDATE,
    date_limite_reponse  DATE,
    statut               VARCHAR2(20) DEFAULT 'ENVOYEE' NOT NULL,
    date_reponse         DATE,
    CONSTRAINT fk_prop_candidature FOREIGN KEY (id_candidature) REFERENCES candidature(id),
    CONSTRAINT ck_prop_statut CHECK (statut IN ('ENVOYEE', 'ACCEPTEE', 'REFUSEE', 'EXPIREE'))
);

-- =====================================================================
-- 13. contrat  (Bloc 4 : plusieurs contrats successifs possibles)
-- =====================================================================
CREATE TABLE contrat (
    id            NUMBER PRIMARY KEY,
    id_employe    NUMBER NOT NULL,
    id_poste      NUMBER NOT NULL,
    type_contrat  VARCHAR2(20) NOT NULL,
    date_debut    DATE NOT NULL,
    date_fin      DATE,
    salaire       NUMBER(15, 2),
    statut        VARCHAR2(20) DEFAULT 'ACTIF' NOT NULL,
    CONSTRAINT fk_contrat_employe FOREIGN KEY (id_employe) REFERENCES employeEntreprise(id),
    CONSTRAINT fk_contrat_poste   FOREIGN KEY (id_poste)   REFERENCES poste(id),
    CONSTRAINT ck_contrat_type    CHECK (type_contrat IN ('CDI', 'CDD', 'STAGE', 'FREELANCE', 'RENOUVELLEMENT')),
    CONSTRAINT ck_contrat_statut  CHECK (statut IN ('ACTIF', 'TERMINE', 'RESILIE')),
    CONSTRAINT ck_contrat_dates   CHECK (date_fin IS NULL OR date_fin >= date_debut)
);

-- =====================================================================
-- 14. posteEmploye  (affectation d'un employé à un poste)
-- =====================================================================
CREATE TABLE posteEmploye (
    id          NUMBER PRIMARY KEY,
    id_poste    NUMBER NOT NULL,
    id_employe  NUMBER NOT NULL,
    id_contrat  NUMBER,
    dateDebut   DATE,
    dateFin     DATE,
    CONSTRAINT fk_poste_emp_poste   FOREIGN KEY (id_poste)   REFERENCES poste(id),
    CONSTRAINT fk_poste_emp_employe FOREIGN KEY (id_employe) REFERENCES employeEntreprise(id),
    CONSTRAINT fk_poste_emp_contrat FOREIGN KEY (id_contrat) REFERENCES contrat(id)
);

-- =====================================================================
-- 15. documentCandidat  (CV, diplômes, pièces jointes)
-- =====================================================================
CREATE TABLE documentCandidat (
    id              NUMBER PRIMARY KEY,
    id_candidat     NUMBER NOT NULL,
    id_candidature  NUMBER,
    type_document   VARCHAR2(30) NOT NULL,
    nom_fichier     VARCHAR2(255) NOT NULL,
    chemin_fichier  VARCHAR2(500) NOT NULL,
    date_upload     DATE DEFAULT SYSDATE,
    CONSTRAINT fk_doc_candidat    FOREIGN KEY (id_candidat)    REFERENCES candidat(id),
    CONSTRAINT fk_doc_candidature FOREIGN KEY (id_candidature) REFERENCES candidature(id),
    CONSTRAINT ck_doc_type CHECK (type_document IN ('CV', 'LETTRE_MOTIVATION', 'DIPLOME', 'AUTRE'))
);

-- =====================================================================
-- 16. notification  (confirmation d'inscription, convocation entretien...)
-- =====================================================================
CREATE TABLE notification (
    id           NUMBER PRIMARY KEY,
    id_candidat  NUMBER,
    id_employe   NUMBER,
    sujet        VARCHAR2(200) NOT NULL,
    message      VARCHAR2(4000),
    date_envoi   DATE DEFAULT SYSDATE,
    lu           NUMBER(1) DEFAULT 0 NOT NULL,
    CONSTRAINT fk_notif_candidat FOREIGN KEY (id_candidat) REFERENCES candidat(id),
    CONSTRAINT fk_notif_employe  FOREIGN KEY (id_employe)  REFERENCES employeEntreprise(id),
    CONSTRAINT ck_notif_dest CHECK (id_candidat IS NOT NULL OR id_employe IS NOT NULL),
    CONSTRAINT ck_notif_lu   CHECK (lu IN (0, 1))
);

-- =====================================================================
-- TRIGGERS D'AUTO-INCREMENT (remplacent IDENTITY)
-- L'id n'est généré que s'il n'est pas fourni à l'INSERT.
-- =====================================================================
CREATE OR REPLACE TRIGGER trg_bi_departement
BEFORE INSERT ON departement
FOR EACH ROW
WHEN (NEW.id IS NULL)
BEGIN
    :NEW.id := seq_departement.NEXTVAL;
END;
/

CREATE OR REPLACE TRIGGER trg_bi_poste
BEFORE INSERT ON poste
FOR EACH ROW
WHEN (NEW.id IS NULL)
BEGIN
    :NEW.id := seq_poste.NEXTVAL;
END;
/

CREATE OR REPLACE TRIGGER trg_bi_candidat
BEFORE INSERT ON candidat
