-- =====================================================================
-- INDEX SUR LES CLÉS ÉTRANGÈRES
-- =====================================================================
CREATE INDEX idx_poste_dept         ON poste(id_dept);
CREATE INDEX idx_demande_poste      ON demandeRecru(id_poste);
CREATE INDEX idx_demande_statut     ON demandeRecru(statut);
CREATE INDEX idx_validation_demande ON validation(id_demande);
CREATE INDEX idx_offre_demande      ON offreEmploi(id_demande);
CREATE INDEX idx_offre_statut       ON offreEmploi(statut);
CREATE INDEX idx_cand_candidat      ON candidature(id_candidat);
CREATE INDEX idx_cand_offre         ON candidature(id_offre);
CREATE INDEX idx_entretien_cand     ON entretien(id_candidature);
CREATE INDEX idx_eval_entretien     ON evaluationCandidat(id_entretien);
CREATE INDEX idx_contrat_employe    ON contrat(id_employe);
CREATE INDEX idx_posteemp_employe   ON posteEmploye(id_employe);

-- =====================================================================
-- VUES
-- =====================================================================

-- Page publique : offres ouvertes
CREATE OR REPLACE VIEW v_offres_publiees AS
SELECT o.id, o.titre, o.description_offre, o.profil_recherche, o.type_contrat,
       o.lieu, o.nb_postes, o.date_publication, o.date_cloture,
       p.nom AS poste, d.nom AS departement
FROM offreEmploi o
JOIN demandeRecru dr ON dr.id = o.id_demande
JOIN poste p         ON p.id  = dr.id_poste
JOIN departement d   ON d.id  = p.id_dept
WHERE o.statut = 'PUBLIEE'
  AND (o.date_cloture IS NULL OR o.date_cloture >= TRUNC(SYSDATE));

-- Suivi RH des candidatures
CREATE OR REPLACE VIEW v_candidatures_detail AS
SELECT ca.id AS id_candidature, ca.etat, ca.date_candidature,
       c.id AS id_candidat, c.nom, c.prenom, c.email, c.telephone,
       o.id AS id_offre, o.titre AS offre
FROM candidature ca
JOIN candidat c    ON c.id = ca.id_candidat
JOIN offreEmploi o ON o.id = ca.id_offre;

-- Planning des entretiens
CREATE OR REPLACE VIEW v_planning_entretiens AS
SELECT e.id, e.date_entretien, e.type_entretien, e.mode_entretien, e.lieu, e.etat,
       c.nom || ' ' || c.prenom   AS candidat,
       o.titre                    AS offre,
       emp.nom || ' ' || emp.prenom AS recruteur
FROM entretien e
JOIN candidature ca        ON ca.id  = e.id_candidature
JOIN candidat c            ON c.id   = ca.id_candidat
JOIN offreEmploi o         ON o.id   = ca.id_offre
JOIN employeEntreprise emp ON emp.id = e.id_employe;

-- =====================================================================
-- TRIGGER : la demande passe à VALIDEE quand la Direction approuve,
--           ou à REFUSEE dès qu'un valideur refuse
-- =====================================================================
CREATE OR REPLACE TRIGGER trg_validation_maj_demande
AFTER INSERT OR UPDATE OF etat ON validation
FOR EACH ROW
BEGIN
    IF :NEW.etat = 'REFUSEE' THEN
        UPDATE demandeRecru SET statut = 'REFUSEE' WHERE id = :NEW.id_demande;
    ELSIF :NEW.etat = 'APPROUVEE' AND :NEW.role_valideur = 'DIRECTION' THEN
        UPDATE demandeRecru SET statut = 'VALIDEE' WHERE id = :NEW.id_demande;
    END IF;
END;
/

-- =====================================================================
-- FLUX GLOBAL
-- 1. Manager crée une demandeRecru (poste existant ou nouveau poste)
-- 2. validation : MANAGER -> RH -> DIRECTION   => demande VALIDEE
-- 3. RH crée une offreEmploi (BROUILLON -> PUBLIEE)
-- 4. Le candidat s'inscrit sur la page (candidat) puis postule (candidature)
-- 5. RH présélectionne, planifie les entretiens (entretien),
--    puis note (evaluationCandidat)
-- 6. propositionEmbauche ACCEPTEE => création employeEntreprise (+ matricule),
--    contrat et posteEmploye (affectation)
-- =====================================================================